"use strict";

const buildingArt = {
  farms:"data:image/png;base64,",
  towns:"data:image/png;base64,",
  nodes:"data:image/png;base64,",
  workshops:"data:image/png;base64,",
  guilds:"data:image/png;base64,",
  barracks:"data:image/png;base64,",
  fortresses:"data:image/png;base64,",
  barriers:"data:image/png;base64,"
};

function buildTurnLabel(key){
  if(key==="barriers") return "No se combina con otros edificios";
  return "El coste final depende del lote y de tus Talleres";
}
function buildCostLabel(key,cost){
  if(key==="barriers") return "1 turno / unidad";
  return cost + " turnos base";
}
function buildCard(key,meta,buildings){
  const [name,desc,cost]=meta;
  const barrier=key==="barriers";
  return `<article class="building-card ${barrier?"barrier-card":""}" data-building-card="${key}">
    <div class="building-card-art" aria-hidden="true">
      <span class="building-art-halo"></span>
      <img src="${buildingArt[key]||buildingArt.fortresses}" alt="" decoding="async" />
    </div>
    <div class="building-card-body">
      <div class="building-card-head">
        <div>
          <span class="building-type">${barrier?"DEFENSA ARCANA":"EDIFICIO"}</span>
          <h3>${esc(name)}</h3>
        </div>
        <div class="building-current"><span>ACTUAL</span><strong>${n(buildings[key])}</strong></div>
      </div>
      <p>${esc(desc)}</p>
      <div class="building-card-controls">
        <div class="building-cost">
          <span>COSTE</span>
          <strong>${esc(buildCostLabel(key,cost))}</strong>
          <small>${esc(buildTurnLabel(key))}</small>
        </div>
        <label class="building-quantity">
          <span>A CONSTRUIR</span>
          <input data-building="${key}" aria-label="Cantidad de ${esc(name)} a construir" type="number" min="0" max="9999" step="1" value="0" inputmode="numeric" />
        </label>
      </div>
    </div>
  </article>`;
}
function refreshBuildPlan(){
  let total=0,types=0,hasBarriers=false,hasOthers=false;
  $$("[data-building]").forEach(input=>{
    const q=Math.max(0,Math.floor(Number(input.value)||0));
    const key=input.dataset.building;
    input.closest(".building-card")?.classList.toggle("selected",q>0);
    if(q>0){
      total+=q; types+=1;
      if(key==="barriers") hasBarriers=true;
      else hasOthers=true;
    }
  });
  const mixed=hasBarriers&&hasOthers;
  const summary=$("#build-plan-summary");
  const warning=$("#build-plan-warning");
  const button=$("#build-button");
  if(summary){
    summary.innerHTML=total
      ? `<span>LOTE PREPARADO</span><strong>${n(total)} unidades</strong><small>${n(types)} ${types===1?"tipo seleccionado":"tipos seleccionados"}</small>`
      : `<span>LOTE PREPARADO</span><strong>Sin selección</strong><small>Indica cuántos edificios quieres levantar.</small>`;
  }
  warning?.classList.toggle("hidden",!mixed);
  if(button) button.disabled=!total||mixed;
}
function renderBuild(){
  const b=realmState.buildings,r=realmState.realm;
  const cards=Object.entries(buildMeta).map(([key,meta])=>buildCard(key,meta,b)).join("");
  const totalBuilt=Object.values(b).reduce((sum,value)=>sum+Math.max(0,Number(value)||0),0);
  const progression=typeof realmProgressLabel==="function"?realmProgressLabel(r.land):{name:"Dominio arcano",level:0};

  $("#view-host").innerHTML=`${viewHeader(
    "ARQUITECTURA",
    "Construcción",
    `Transforma tus ${n(r.wilderness)} acres salvajes en infraestructura para tu reino.`
  )}
  <section class="construction-hero">
    <div class="construction-hero-copy">
      <span class="section-kicker">MAESTRÍA DEL REINO</span>
      <h3>Diseña el crecimiento de tu dominio</h3>
      <p>Construye en lotes, protege tu economía y usa Talleres para acelerar las obras futuras. El coste real de turnos se calcula al confirmar el lote.</p>
      <div class="construction-metrics">
        <div><span>TERRENO SALVAJE</span><strong>${n(r.wilderness)}</strong><small>acres disponibles</small></div>
        <div><span>TALLERES</span><strong>${n(b.workshops)}</strong><small>aceleran la construcción</small></div>
        <div><span>EDIFICIOS</span><strong>${n(totalBuilt)}</strong><small>estructuras levantadas</small></div>
      </div>
    </div>
    <div class="construction-hero-art">
      <img src="assets/art/kingdom-level-00.svg?v=0.2.23" alt="" aria-hidden="true" decoding="async" />
      <div class="construction-art-shade" aria-hidden="true"></div>
      <div class="construction-art-caption">
        <span>${esc(progression.name)}</span>
        <small>ARTE DEL REINO · BETA</small>
      </div>
    </div>
  </section>
  <section class="construction-shell">
    <div class="construction-section-head">
      <div>
        <span class="section-kicker">CATÁLOGO DE OBRAS</span>
        <h3>Elige qué levantar</h3>
        <p>Cada tarjeta muestra tus edificios actuales, el coste base y la cantidad que vas a añadir al lote.</p>
      </div>
      <div class="construction-section-mark" aria-hidden="true">⌂</div>
    </div>
    <div class="building-grid">${cards}</div>
    <div id="build-plan-warning" class="notice error hidden construction-warning">Las Barreras deben construirse en una orden separada. Retira los demás edificios del lote para continuar.</div>
    <div class="construction-turn-note">
      <div class="construction-note-icon" aria-hidden="true">✦</div>
      <div><strong>Cómo se gastan los turnos</strong><span>Las Barreras consumen 1 turno por unidad. En el resto de edificios, el gasto depende del tamaño total del lote y de tus Talleres. El resultado exacto se muestra al completar la construcción.</span></div>
    </div>
    <div class="construction-actionbar">
      <div id="build-plan-summary" class="build-plan-summary"><span>LOTE PREPARADO</span><strong>Sin selección</strong><small>Indica cuántos edificios quieres levantar.</small></div>
      <button id="build-button" class="primary-action build-submit" disabled>✦ CONSTRUIR LOTE</button>
    </div>
  </section>`;

  $$("[data-building]").forEach(input=>input.addEventListener("input",refreshBuildPlan));
  $("#build-button").addEventListener("click",()=>doBuild($("#build-button")));
  refreshBuildPlan();
}
async function doBuild(btn){
  const plan={};
  $$("[data-building]").forEach(input=>{
    const q=Math.max(0,Math.floor(Number(input.value)||0));
    if(q) plan[input.dataset.building]=q;
  });
  if(!Object.keys(plan).length){toast("Indica al menos un edificio.","error");return;}
  if(plan.barriers && Object.keys(plan).some(key=>key!=="barriers")){toast("Las Barreras deben construirse en una orden separada.","error");return;}
  await actionCall(btn,()=>rpc("build",{p_plan:plan}),null,res=>`Construcción completada. ${n(res.turns_spent)} turnos consumidos.`);
}
